const body = $input.first().json.body ?? $input.first().json;
const transcript = body.transcript ?? '';
const externalCallId = body.externalCallId ?? body.captureId ?? `call-${Date.now()}`;
const kind = body.kind ?? 'seller-call';

if (!transcript.trim()) {
  throw new Error('transcript is required. Run stt/transcribe.py on audio first, or POST transcript in body.');
}

const sharedGuidelines = `- Every field is nullable unless explicitly required by schema.
- High-stakes fields (price, APN, dates) MUST use {value, quote} — drop value if quote is missing.
- Never invent data not spoken or clearly implied in the transcript.`;

const sellerPrompt = `# Seller Call Extraction — System Prompt

You extract structured RE acquisition data from seller/broker call transcripts.

${sharedGuidelines}

Focus on seller motivation, asking price, property address, APN, timeline, condition, objections, follow-up, deal type hints.

Respond with ONLY valid JSON matching SellerCallExtraction schema. Set extractionMeta.externalCallId to the provided id.`;

return [{
  json: {
    transcript,
    externalCallId,
    kind,
    systemPrompt: kind === 'site-memo'
      ? sellerPrompt.replace('Seller Call', 'Site Memo')
      : sellerPrompt,
  },
}];

