const { v5: uuidv5 } = require('uuid');
const NS = '6ba7b810-9dad-11d1-80b4-00c04fd430c8';
const did = (seed, label) => uuidv5(`${seed}:${label}`, NS);

const ollama = $input.first().json;
const prev = $('Normalize Input').first().json;
const transcript = prev.transcript;
const callId = prev.externalCallId;

let raw = ollama.message?.content ?? '';
let extraction;
try {
  extraction = JSON.parse(raw);
} catch {
  const m = raw.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('Ollama returned non-JSON');
  extraction = JSON.parse(m[0]);
}
if (!extraction.extractionMeta) extraction.extractionMeta = {};
extraction.extractionMeta.externalCallId = extraction.extractionMeta.externalCallId || callId;

const identity = extraction.identity || {};
const disposition = extraction.disposition || {};

const toAddress = (addr) => {
  if (!addr) return null;
  if (addr.addressStreet1) return addr;
  return {
    addressStreet1: addr.street1 || '',
    addressStreet2: addr.street2 || null,
    addressCity: addr.city || '',
    addressState: addr.state || '',
    addressPostcode: addr.zip || '',
    addressCountry: 'United States',
  };
};

const address = toAddress(identity.propertyAddress);
const addressKey = address ? `${address.addressStreet1}|${address.addressCity}|${address.addressState}|${address.addressPostcode}` : callId;

const propertyId = did(addressKey, 'property');
const opportunityId = did(callId, 'opportunity');
const personId = identity.leadPhoneE164 ? did(identity.leadPhoneE164, 'person') : null;
const transcriptId = did(callId, 'callTranscript');

const toCurrency = (v) => {
  const num = typeof v === 'object' ? v?.value : v;
  if (num == null) return null;
  return { amountMicros: Math.round(Number(num) * 1e6), currencyCode: 'USD' };
};

return [{
  json: {
    extraction,
    transcript,
    callId,
    propertyId,
    opportunityId,
    personId,
    transcriptId,
    propertyPayload: {
      id: propertyId,
      ...(address ? { propertyAddress: address } : {}),
      ...(identity.apn?.value ? { apn: identity.apn.value } : {}),
    },
    opportunityPayload: {
      id: opportunityId,
      name: address?.addressStreet1 ? `${address.addressStreet1} — Seller call` : `Seller call ${callId.slice(0,8)}`,
      propertyId,
      ...(address ? { propertyAddress: address } : {}),
      dealStage: 'QUALIFYING',
      ...(identity.leadSource ? { leadSource: identity.leadSource } : {}),
      ...(disposition.sellerMotivation ? { motivation: disposition.sellerMotivation } : {}),
      ...(disposition.dealTypeHint ? { dealType: disposition.dealTypeHint } : {}),
      ...(toCurrency(disposition.askingPrice) ? { askingPrice: toCurrency(disposition.askingPrice) } : {}),
    },
    personPayload: personId ? {
      id: personId,
      ...(identity.sellerEmail ? { emails: { primaryEmail: identity.sellerEmail, additionalEmails: [] } } : {}),
    } : null,
    transcriptPayload: {
      id: transcriptId,
      transcriptBody: { markdown: transcript, blocknote: null },
      callOutcome: disposition.callOutcome || 'CONNECTED',
      extractedData: extraction,
      transcriptOpportunityId: opportunityId,
      ...(personId ? { transcriptPersonId: personId } : {}),
    },
  },
}];
